    UI_VIRUS_APPLY_VIRUS: "Apply virus database",
    UI_VIRUS_APPLY_VIRUS_SET : "Set Default Virus Database",
    UI_VIRUS_CLAMAV_DETAIL: "ClamAV is an open-source virus scanning engine, a global open-source project maintained and contributed by developers from around the world. Since its inception, ClamAV has earned widespread recognition in the information security field due to its powerful detection capabilities and continuously updated virus database. Through years of continuous optimization and development, ClamAV has accumulated rich virus identification techniques and experience, becoming a trusted virus scanning solution for many users. Its core product, the ClamAV virus scanning software, is highly regarded by many independent evaluation agencies and security experts as a recommended virus protection tool due to its efficiency, accuracy, and lightweight features.",
    UI_VIRUS_KAV_DETAIL: "Kaspersky Anti-Virus SDK is a professional-grade malware detection solution provided by Kaspersky Lab. It uses the advanced SafeStream scanning engine and real-time updated global threat intelligence database to accurately identify various types of malicious programs such as viruses, Trojans, and ransomware. It boasts high detection rates and low false positives. This SDK supports cross-platform deployment (including x86, ARM, and MIPS architectures) and provides lightweight API interfaces that can be quickly integrated into network devices, security gateways, and enterprise security systems, offering enterprise-level security protection capabilities for various hardware devices and software solutions.",
